SELECT T0."DocNum" as "STR No",T0."U_MEPSDT", T0."U_MEREQBY", T0."U_MEFWHSNM", T0."U_METWHSNM", T0."CreateDate", T0."CreateTime" FROM "@ME_STR"  T0 WHERE T0."U_MEFWHSCD" ='DIF1' and  T0."U_MESTS" ='Open'  and T0."CreateDate"=CURRENT_DATE  and  LEFT(LPAD(T0."CreateTime",4,'0'),4)>=TO_CHAR(ADD_SECONDS(CURRENT_TIMESTAMP,-600), 'HH24MI')
